sys_script_include.script:
var InviteTokenService = Class.create();
InviteTokenService.prototype = {

    initialize: function() {},

    generateToken: function(accessSysId, expiryDays) {
        expiryDays = expiryDays || 7;

        var token   = this._createRandomToken();
        var expires = new GlideDateTime();
        expires.addDaysLocalTime(expiryDays);

        var gr = new GlideRecord('x_863027_invite_0_invite_token');
        gr.initialize();
        gr.u_access     = accessSysId;
        gr.u_token      = token;
        gr.u_expires_at = expires;
        gr.u_state      = 'active';
        gr.insert();

        gs.info('InviteTokenService.generateToken: Token erstellt für Access ' + accessSysId);
        return token;
    },

    validate: function(token) {
        var gr = new GlideRecord('x_863027_invite_0_invite_token');
        gr.addQuery('u_token', token);
        gr.addQuery('u_state', 'active');
        gr.setLimit(1);
        gr.query();

        if (!gr.next()) {
            return { valid: false, reason: 'invalid_token' };
        }

        // Ablauf prüfen
        var now     = new GlideDateTime();
        var expires = new GlideDateTime(gr.getValue('u_expires_at'));
        if (expires.before(now)) {
            gr.u_state = 'expired';
            gr.update();
            return { valid: false, reason: 'token_expired' };
        }

        // Access-Record laden
        var accessGr = new GlideRecord('x_863027_invite_0_invite_access');
        if (!accessGr.get(gr.getValue('u_access'))) {
            return { valid: false, reason: 'access_not_found' };
        }

        return {
            valid:        true,
            tokenRecord:  gr,
            accessRecord: accessGr
        };
    },

    markUsed: function(tokenRecord) {
        tokenRecord.u_state   = 'used';
        tokenRecord.u_used_at = new GlideDateTime();
        tokenRecord.update();
    },

    _createRandomToken: function() {
        var random = new GlideSecureRandomUtil();
        return random.getSecureRandomString(64);
    },

    type: 'InviteTokenService'
};
